def one_admin_each(apps, schema_editor):
    """REQ-045: an organization has exactly one admin. Where several held the Admin role, the creator (or
    else the longest-standing) keeps it and the others move to the Committee role, so nobody is locked out
    of what they ran; they are listed as handed over in the history."""
    Organization = apps.get_model("organizations", "Organization")
    Membership = apps.get_model("organizations", "Membership")
    AdminHandover = apps.get_model("organizations", "AdminHandover")
    for organization in Organization.objects.all():
        admin_role = organization.roles.filter(key="admin").first()
        committee = organization.roles.filter(key="committee").first()
        if admin_role is None:
            continue
        holders = list(
            Membership.objects.filter(organization=organization, status="active", roles=admin_role)
            .select_related("user")
            .order_by("joined_at")
        )
        if len(holders) < 2:
            continue
        keeper = next((m for m in holders if m.user_id == organization.created_by_id and m.user.is_active), None)
        keeper = keeper or next((m for m in holders if m.user.is_active), holders[0])
        for membership in holders:
            if membership.pk == keeper.pk:
                continue
            membership.roles.remove(admin_role)
            if committee:
                membership.roles.add(committee)
            AdminHandover.objects.create(
                organization=organization,
                kind="appointment",
                status="accepted",
                from_user=membership.user,
                to_user=keeper.user,
                reason="One admin per organization (REQ-045)",
            )


